mesSim(document.getElementById("sim-l77"),Object.assign({id:"l77"},{kind:"api",title:"Bộ nhận lệnh ERP",sub:"Mô phỏng: mỗi lần Gửi coi như một file mới trong inbox/. Kết quả cho biết file chuyển sang done/ hay error/.",
 store:{products:["SP-07","SP-08"],wo:[],n:412},method:"POST",path:"/inbox",body:"{\n  \"erp_ref\": \"ERP-88121\",\n  \"product_id\": \"SP-07\",\n  \"qty\": 6000,\n  \"line_id\": \"L1\",\n  \"due\": \"2026-11-10T14:00:00+07:00\"\n}",rows:9,
 routes:[{m:"POST",p:"/inbox",d:"nhận một file lệnh",schema:{erp_ref:{t:"str",re:"^ERP-\\d+$"},product_id:{t:"str"},qty:{t:"int",gt:0},line_id:{t:"str"},due:{t:"dt",tz:1}},
   h:({body,store})=>{if(!store.products.includes(body.product_id))return{status:422,body:{detail:"sản phẩm chưa khai báo",file:"error/"}};
     const d=store.wo.find(w=>w.erp_ref===body.erp_ref);if(d)return{status:200,body:{result:"trùng, bỏ qua (ON CONFLICT DO NOTHING)",wo_id:d.wo_id,file:"done/"}};
     const w=Object.assign({wo_id:"WO-0"+store.n++,status:"NEW"},body);store.wo.push(w);return{status:201,body:{wo_id:w.wo_id,status:"NEW",file:"done/"}}}},
  {m:"GET",p:"/work-orders",d:"lệnh đã nhận",h:({store})=>({status:200,body:store.wo.map(w=>({wo_id:w.wo_id,erp_ref:w.erp_ref,qty:w.qty,status:w.status}))})}],
 samples:[{l:"File có sẵn",m:"POST",p:"/inbox",b:"{\n  \"erp_ref\": \"ERP-88121\",\n  \"product_id\": \"SP-07\",\n  \"qty\": 6000,\n  \"line_id\": \"L1\",\n  \"due\": \"2026-11-10T14:00:00+07:00\"\n}"},{l:"qty = 0",m:"POST",p:"/inbox",b:'{"erp_ref": "ERP-88122", "product_id": "SP-07", "qty": 0, "line_id": "L1", "due": "2026-11-10T14:00:00+07:00"}'},
  {l:"JSON hỏng",m:"POST",p:"/inbox",b:'{"erp_ref": "ERP-88123", "qty": 6000,'},{l:"Danh sách lệnh",m:"GET",p:"/work-orders"}],
 tasks:[{t:"Gửi file có sẵn: tạo lệnh mới.",check:(s,c)=>c.has("http",e=>e.status===201)},
  {t:"Gửi lại đúng file đó (ERP gửi lặp).",ok:"Không có lệnh thứ hai: UNIQUE (erp_ref) + ON CONFLICT DO NOTHING; file vẫn vào done/.",check:(s,c)=>c.has("http",e=>e.status===200&&e.body&&e.body.result)},
  {t:"Gửi file có qty = 0 và một file JSON hỏng.",ok:"Pydantic chặn trước khi chạm CSDL; file vào error/ kèm lý do.",check:(s,c)=>c.has("http",e=>e.status===422&&/greater_than/.test(JSON.stringify(e.body)))&&c.has("http",e=>/json_invalid/.test(JSON.stringify(e.body)))},
  {t:"Gửi lệnh mới ERP-88130 cho sản phẩm SP-99.",ok:"Định dạng đúng nhưng sản phẩm chưa khai báo trong MES: error/.",check:(s,c)=>c.has("http",e=>e.status===422&&/chưa khai báo/.test(JSON.stringify(e.body)))},
  {t:"Xem danh sách lệnh: có mấy lệnh?",check:(s,c)=>c.has("http",e=>e.m==="GET"&&e.status===200&&Array.isArray(e.body))}]}));

